def can_chain(dominoes):
    if not dominoes:
        return []

    def backtrack(remaining, chain, end):
        if not remaining:
            return chain if chain[0][0] == end else None
        for i, (a, b) in enumerate(remaining):
            if a == end:
                result = backtrack(
                    remaining[:i] + remaining[i + 1:], chain + [(a, b)], b
                )
                if result is not None:
                    return result
            if b == end and b != a:
                result = backtrack(
                    remaining[:i] + remaining[i + 1:], chain + [(b, a)], a
                )
                if result is not None:
                    return result
        return None

    for i, (a, b) in enumerate(dominoes):
        rest = dominoes[:i] + dominoes[i + 1:]
        result = backtrack(rest, [(a, b)], b)
        if result is not None:
            return result
        if b != a:
            result = backtrack(rest, [(b, a)], a)
            if result is not None:
                return result
    return None

